CREATE TABLE mission_narrative_internal.editorial_campaigns_v1(
 id uuid PRIMARY KEY,enabled boolean NOT NULL DEFAULT false,policy jsonb NOT NULL,source_refs jsonb NOT NULL,
 policy_sha256 text NOT NULL CHECK(policy_sha256~'^[a-f0-9]{64}$'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 CHECK(jsonb_typeof(policy)='object'),CHECK(jsonb_typeof(source_refs)='array'),CHECK(jsonb_array_length(source_refs)=3)
);
CREATE TABLE mission_narrative_internal.editorial_runs_v1(
 id uuid PRIMARY KEY,campaign_id uuid NOT NULL REFERENCES mission_narrative_internal.editorial_campaigns_v1(id),
 actor_user uuid NOT NULL REFERENCES public.profiles(id),case_no integer NOT NULL CHECK(case_no BETWEEN 1 AND 3),variant text NOT NULL CHECK(variant IN('baseline','canary')),
 request_key uuid NOT NULL UNIQUE,source_work_id uuid NOT NULL REFERENCES mission_generic_owner.work_items(id),
 source jsonb NOT NULL,policy_snapshot jsonb NOT NULL CHECK(jsonb_typeof(policy_snapshot)='object'),source_sha256 text NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'),policy_sha256 text NOT NULL,
 state text NOT NULL DEFAULT 'ready' CHECK(state IN('ready','count_sent','counted','authorized','provider_started','completed','failed','uncertain')),
 receipt_id uuid UNIQUE REFERENCES mission_narrative_internal.dispatch_receipts(id),count_call_id uuid REFERENCES staff_ai_quota_private.calls(id),generation_call_id uuid REFERENCES staff_ai_quota_private.calls(id),
 request_text text,request_sha256 text CHECK(request_sha256~'^[a-f0-9]{64}$'),count_input_tokens integer CHECK(count_input_tokens>=0),
 authorization_id uuid REFERENCES mission_narrative_internal.provider_authorizations(id),raw_text text,raw_sha256 text CHECK(raw_sha256~'^[a-f0-9]{64}$'),
 result jsonb,result_sha256 text CHECK(result_sha256~'^[a-f0-9]{64}$'),reason_code text,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),retained_at timestamptz,finalized_at timestamptz,
 UNIQUE(campaign_id,case_no,variant),CHECK((state IN('completed','failed','uncertain'))=(finalized_at IS NOT NULL)),
 CHECK((raw_text IS NULL)=(raw_sha256 IS NULL)),CHECK((result IS NULL)=(result_sha256 IS NULL))
);
ALTER TABLE mission_narrative_internal.editorial_campaigns_v1 ENABLE ROW LEVEL SECURITY;
ALTER TABLE mission_narrative_internal.editorial_runs_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON mission_narrative_internal.editorial_campaigns_v1,mission_narrative_internal.editorial_runs_v1 FROM PUBLIC,anon,authenticated,service_role;

CREATE TABLE mission_narrative_internal.editorial_audit_v1(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES mission_narrative_internal.editorial_runs_v1(id),event_code text NOT NULL,details jsonb NOT NULL CHECK(jsonb_typeof(details)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE mission_narrative_internal.editorial_audit_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON mission_narrative_internal.editorial_audit_v1 FROM PUBLIC,anon,authenticated,service_role;

