 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare r mission_narrative_internal.dispatch_receipts%rowtype;pol mission_narrative_internal.runtime_policy%rowtype;ub numeric;spent_run numeric;spent_day numeric;spent_all numeric;raw text;a uuid;pub uuid;begin perform mission_narrative_internal.worker(p_worker_token); IF EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts av_receipt WHERE av_receipt.id=p_receipt AND av_receipt.event_kind='mission_generic_event') THEN -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
