 pol.max_input_tokens:=(select (ec.policy->>'max_input_tokens')::integer from mission_narrative_internal.editorial_campaigns_v1 ec where ec.id=(r.envelope->>'campaign_id')::uuid);
 pol.max_output_tokens:=(select (ec.policy->>'max_output_tokens')::integer from mission_narrative_internal.editorial_campaigns_v1 ec where ec.id=(r.envelope->>'campaign_id')::uuid);
 pol.enabled:=true;
elsif r.event_kind='mission_opening_preview' and mission_academy_owner.staff_carrier_runtime(r.master_session_id) then pol.enabled:=true;end if;ub:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;select coalesce(sum(case when status in('success','fallback','unknown_billable') or (quest_compile_request is not null and status='failed') then charged_cost_usd else coalesce(upper_bound_cost_usd,0) end),0) into spent_run from mission_narrative_internal.dispatch_receipts where master_session_id=r.master_session_id;select coalesce(sum(case when status in('success','fallback','unknown_billable') or (quest_compile_request is not null and status='failed') then charged_cost_usd else coalesce(upper_bound_cost_usd,0) end),0) into spent_day from mission_narrative_internal.dispatch_receipts where created_at>=date_trunc('day',clock_timestamp());select coalesce(sum(case when status in('success','fallback','unknown_billable') or (quest_compile_request is not null and status='failed') then charged_cost_usd else coalesce(upper_bound_cost_usd,0) end),0) into spent_all from mission_narrative_internal.dispatch_receipts;
